 "content": "def transform(grid):
    """Replace each nonzero input cell with a 3x3 copy of the zero-cell mask."""
    h, w = len(grid), len(grid[0])
    out = [[0] * (3 * w) for _ in range(3 * h)]
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value != 0:
                for i in range(h):
                    for j in range(w):
                        if grid[i][j] == 0:
                            out[3 * r + i][3 * c + j] = value
    return out
